window.docContents[224].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___11___-Historical-interlude___-Georg-Frobenius___s-___Principle-of-Horse-Trade___/Section-4___11___-Historical-interlude-___-Georg-Frobenius___s-Principle-of-Horse-Trade/#Chapter4___Discussion_4___11":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.11. Historical interlude: Georg Frobenius's \"Principle of Horse Trade\"\tSection 4.11: Historical interlude — Georg Frobenius's Principle of Horse Trade","header":"Section 4.11: Historical interlude — Georg Frobenius's Principle of Horse Trade","id":"/4___-Representations-of-finite-groups___-Basic-results/4___11___-Historical-interlude___-Georg-Frobenius___s-___Principle-of-Horse-Trade___/Section-4___11___-Historical-interlude-___-Georg-Frobenius___s-Principle-of-Horse-Trade/#Chapter4___Discussion_4___11"},"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Convention___-algebra-means-associative-algebra-with-unit/#Chapter2___Discussion_after_Proposition2___2___3":{"contents":"From now on, by an algebra A we will mean an associative algebra with a unit.\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.2. Algebras\tConvention: algebra means associative algebra with unit","header":"Convention: algebra means associative algebra with unit","id":"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Convention___-algebra-means-associative-algebra-with-unit/#Chapter2___Discussion_after_Proposition2___2___3"},"/5___-Representations-of-finite-groups___-Further-results/5___14___-Induced-representations-for-___S_n___/Proof-of-Proposition-5___14___1/#Chapter5___Discussion_proof_of_Proposition5___14___1":{"contents":"Proof. By Lemmas 5.13.3 and 5.13.4,\n\n\\operatorname{Hom}(U_\\lambda, V_\\mu) = \\operatorname{Hom}(\\mathbb{C}[S_n]a_\\lambda, \\mathbb{C}[S_n]a_\\mu b_\\mu) = a_\\lambda \\mathbb{C}[S_n] a_\\mu b_\\mu,\n\nand the result follows from Lemmas 5.13.1 and 5.13.2. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.14. Induced representations for $S_n$\tProof of Proposition 5.14.1","header":"Proof of Proposition 5.14.1","id":"/5___-Representations-of-finite-groups___-Further-results/5___14___-Induced-representations-for-___S_n___/Proof-of-Proposition-5___14___1/#Chapter5___Discussion_proof_of_Proposition5___14___1"},"/2___-Basic-notions-of-representation-theory/2___1___-What-is-representation-theory___/#chapter-02___section-2-1":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory","header":"2.1. What is representation theory?","id":"/2___-Basic-notions-of-representation-theory/2___1___-What-is-representation-theory___/#chapter-02___section-2-1"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Path-algebra-of-a-finite-quiver-has-a-unit/#Chapter2___Remark2___8___5":{"contents":"Remark 2.8.5. It is easy to see that if Q is a finite set then \\sum_{i \\in I} p_i = 1, so P_Q is an algebra with unit.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tPath algebra of a finite quiver has a unit","header":"Path algebra of a finite quiver has a unit","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Path-algebra-of-a-finite-quiver-has-a-unit/#Chapter2___Remark2___8___5"},"/3___-General-results-of-representation-theory/3___9___-Problems/Irreducible-representations-and-Ext___1-for-path-algebras/#Chapter3___Problem3___9___3":{"contents":"Problem 3.9.3. Let Q be a quiver without oriented cycles, and let P_Q be the path algebra of Q. Find irreducible representations of P_Q and compute \\operatorname{Ext}^1 between them. Classify 2-dimensional representations of P_Q.\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.9. Problems\tIrreducible representations and Ext^1 for path algebras","header":"Irreducible representations and Ext^1 for path algebras","id":"/3___-General-results-of-representation-theory/3___9___-Problems/Irreducible-representations-and-Ext___1-for-path-algebras/#Chapter3___Problem3___9___3"},"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/Section-5___25___-Representations-of-GL_2_LPAR_F_q_RPAR_/#Chapter5___Introduction_5___25":{"contents":"\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.25. Representations of $GL_2(\\mathbb{F}_q)$\tSection 5.25: Representations of GL_2(F_q)","header":"Section 5.25: Representations of GL_2(F_q)","id":"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/Section-5___25___-Representations-of-GL_2_LPAR_F_q_RPAR_/#Chapter5___Introduction_5___25"},"/9___-Structure-of-finite-dimensional-algebras/9___2___-Projective-covers/#chapter-09___section-9-2":{"contents":"\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras","header":"9.2. Projective covers","id":"/9___-Structure-of-finite-dimensional-algebras/9___2___-Projective-covers/#chapter-09___section-9-2"}});
